<?php require 'includes/database.php';$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT s.*,COALESCE(AVG(r.rating),0) avg_rating FROM shops s LEFT JOIN reviews r ON r.shop_id=s.id WHERE s.id=? GROUP BY s.id");$st->execute([$id]);$shop=$st->fetch();if(!$shop){http_response_code(404);exit('Shop not found');}$ss=$pdo->prepare("SELECT * FROM services WHERE shop_id=? AND active=1");$ss->execute([$id]);$services=$ss->fetchAll();require 'includes/header.php';?><main class="wrap"><div class="card"><img class="shop-img" style="height:300px" src="<?=htmlspecialchars($shop['image']?:'https://placehold.co/900x400')?>"><h1><?=htmlspecialchars($shop['name'])?></h1><p><?=htmlspecialchars($shop['category'])?> • <span class="stars">★ <?=number_format($shop['avg_rating'],1)?></span></p><p><?=nl2br(htmlspecialchars($shop['address']))?></p><p>เวลาเปิด <?=substr($shop['open_time'],0,5)?> - <?=substr($shop['close_time'],0,5)?></p></div><h2>บริการ</h2><div class="grid"><?php foreach($services as $s):?><div class="card"><h3><?=htmlspecialchars($s['name'])?></h3><p><?=htmlspecialchars($s['description'])?></p><b><?=number_format($s['price'],0)?> บาท</b><br><br><a class="btn" href="booking.php?service_id=<?=$s['id']?>">จองบริการ</a></div><?php endforeach;?></div></main><?php require 'includes/footer.php';?>
